const listSlackMessageFiles = `-- name: ListSlackMessageFiles :many
SELECT a.id, a.disk, a.path FROM attachments a
JOIN messages m ON m.id = a.message_id AND m.workspace_id = a.workspace_id
WHERE a.workspace_id = $1 AND a.message_id = ANY ($2::uuid[])
  AND (m.author_type = 'contact' OR m.dedupe_key IS NOT NULL)
`

type ListSlackMessageFilesParams struct {
	WorkspaceID ids.UUID   `json:"workspace_id"`
	MessageIds  []ids.UUID `json:"message_ids"`
}

type ListSlackMessageFilesRow struct {
	ID   ids.UUID `json:"id"`
	Disk string   `json:"disk"`
	Path string   `json:"path"`
}

// ListSlackMessageFiles returns the stored files of those of the
// messages that Slack brought in.
func (q *Queries) ListSlackMessageFiles(ctx context.Context, arg ListSlackMessageFilesParams) ([]ListSlackMessageFilesRow, error) {
	rows, err := q.db.Query(ctx, listSlackMessageFiles, arg.WorkspaceID, arg.MessageIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListSlackMessageFilesRow
	for rows.Next() {
		var i ListSlackMessageFilesRow
		if err := rows.Scan(&i.ID, &i.Disk, &i.Path); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listSlackOnlyContacts = `-- name: ListSlackOnlyContacts :many
SELECT k.id FROM contacts k
WHERE k.workspace_id = $1 AND k.id = ANY ($2::uuid[]) AND NOT k.placeholder AND k.external_id IS NULL
  AND EXISTS (
      SELECT 1 FROM contact_identities i
      WHERE i.workspace_id = k.workspace_id AND i.contact_id = k.id AND i.type = 'slack_user'
  )
  AND NOT EXISTS (
      SELECT 1 FROM contact_identities i
      WHERE i.workspace_id = k.workspace_id AND i.contact_id = k.id AND i.type <> 'slack_user'
  )
  AND NOT EXISTS (
      SELECT 1 FROM conversations o
      WHERE o.workspace_id = k.workspace_id AND o.contact_id = k.id
        AND o.channel_connection_id <> $3
  )
ORDER BY k.id
`

type ListSlackOnlyContactsParams struct {
	WorkspaceID         ids.UUID   `json:"workspace_id"`
	Ids                 []ids.UUID `json:"ids"`
	ChannelConnectionID ids.UUID   `json:"channel_connection_id"`
}

// ListSlackOnlyContacts returns which of the contacts exist only because
// of the Slack connection: known by a Slack user alone, never named by
// the workspace's own systems, and with no conversation anywhere else.
func (q *Queries) ListSlackOnlyContacts(ctx context.Context, arg ListSlackOnlyContactsParams) ([]ids.UUID, error) {
	rows, err := q.db.Query(ctx, listSlackOnlyContacts, arg.WorkspaceID, arg.Ids, arg.ChannelConnectionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ids.UUID
	for rows.Next() {
		var id ids.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const scrubConnectionBroadcastRecipients = `-- name: ScrubConnectionBroadcastRecipients :execrows
UPDATE broadcast_recipients b
SET address = '', external_ref = NULL, updated_at = $1
FROM channel_rooms r
WHERE b.workspace_id = $2 AND r.workspace_id = b.workspace_id AND r.id = b.room_id
  AND r.channel_connection_id = $3 AND (b.address <> '' OR b.external_ref IS NOT NULL)
`

type ScrubConnectionBroadcastRecipientsParams struct {
	Now                 time.Time `json:"now"`
	WorkspaceID         ids.UUID  `json:"workspace_id"`
	ChannelConnectionID ids.UUID  `json:"channel_connection_id"`
}

// ScrubConnectionBroadcastRecipients forgets where in Slack broadcasts
// were posted to the connection's rooms. The rows stay so a broadcast's
// counts do not change.
func (q *Queries) ScrubConnectionBroadcastRecipients(ctx context.Context, arg ScrubConnectionBroadcastRecipientsParams) (int64, error) {
	result, err := q.db.Exec(ctx, scrubConnectionBroadcastRecipients, arg.Now, arg.WorkspaceID, arg.ChannelConnectionID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const wipeConversationMessages = `-- name: WipeConversationMessages :execrows
UPDATE messages
SET body = CASE WHEN author_type = 'contact' OR dedupe_key IS NOT NULL THEN NULL ELSE body END,
    body_full = CASE WHEN author_type = 'contact' OR dedupe_key IS NOT NULL THEN NULL ELSE body_full END,
    body_html = CASE WHEN author_type = 'contact' OR dedupe_key IS NOT NULL THEN NULL ELSE body_html END,
    metadata = CASE WHEN author_type = 'contact' OR dedupe_key IS NOT NULL THEN '{}' ELSE metadata END,
    deleted_at = CASE WHEN author_type = 'contact' OR dedupe_key IS NOT NULL
        THEN coalesce(deleted_at, $1::timestamptz) ELSE deleted_at END,
    channel_message_id = NULL, dedupe_key = NULL, delivery_error = NULL, updated_at = $1::timestamptz
WHERE workspace_id = $2 AND conversation_id = ANY ($3::uuid[])
  AND (
      channel_message_id IS NOT NULL OR dedupe_key IS NOT NULL OR delivery_error IS NOT NULL
      OR (author_type = 'contact'
          AND (body IS NOT NULL OR body_full IS NOT NULL OR body_html IS NOT NULL OR metadata <> '{}'))
  )
`

type WipeConversationMessagesParams struct {
	Now         time.Time  `json:"now"`
	WorkspaceID ids.UUID   `json:"workspace_id"`
	Ids         []ids.UUID `json:"ids"`
}

// WipeConversationMessages empties the messages Slack brought into the
// conversations, the customer's and a teammate's written in Slack, and
// forgets where on the chat app every message was. A reply written in
// dimmi keeps its words: it is the team's own work, not Slack's data.
// The rows stay, so the timeline and the counts built on it hold.
func (q *Queries) WipeConversationMessages(ctx context.Context, arg WipeConversationMessagesParams) (int64, error) {
	result, err := q.db.Exec(ctx, wipeConversationMessages, arg.Now, arg.WorkspaceID, arg.Ids)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const wipeMessages = `-- name: WipeMessages :execrows
UPDATE messages
SET body = CASE WHEN author_type = 'contact' OR dedupe_key IS NOT NULL THEN NULL ELSE body END,
    body_full = CASE WHEN author_type = 'contact' OR dedupe_key IS NOT NULL THEN NULL ELSE body_full END,
    body_html = CASE WHEN author_type = 'contact' OR dedupe_key IS NOT NULL THEN NULL ELSE body_html END,
    metadata = CASE WHEN author_type = 'contact' OR dedupe_key IS NOT NULL THEN '{}' ELSE metadata END,
    deleted_at = CASE WHEN author_type = 'contact' OR dedupe_key IS NOT NULL
        THEN coalesce(deleted_at, $1::timestamptz) ELSE deleted_at END,
    channel_message_id = NULL, dedupe_key = NULL, delivery_error = NULL, updated_at = $1::timestamptz
WHERE workspace_id = $2 AND id = ANY ($3::uuid[])
`

type WipeMessagesParams struct {
	Now         time.Time  `json:"now"`
	WorkspaceID ids.UUID   `json:"workspace_id"`
	Ids         []ids.UUID `json:"ids"`
}

// WipeMessages empties the messages, as WipeConversationMessages does.
func (q *Queries) WipeMessages(ctx context.Context, arg WipeMessagesParams) (int64, error) {
	result, err := q.db.Exec(ctx, wipeMessages, arg.Now, arg.WorkspaceID, arg.Ids)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
